GENES = list(GENES_ALL)  # kept as a separate name for compatibility -- same list, same order

# NOTE: a handful of offsets appear twice in GENES_ALL (see module docstring) -- this dict
# keeps whichever one was defined last for any lookup that only wants "a" gene for an offset
# (e.g. nothing in the GUI currently does this for a duplicated offset; each GeneRow carries
# its own full gene dict already, so this is only for convenience/external use).
GENE_BY_OFFSET = {g["offset"]: g for g in GENES_ALL}

# Tab order -- first-seen order of `section` across GENES_ALL, i.e. the guide's own <h2> order.
SECTIONS = ['Fins', 'Body', 'Other']

